var i=`0069-halaszle`;var n=`world-0069`;var a=`HU`;var s=`eastern-europe`;var o=4;var r=45;var l={en:`Halászlé`,ua:`Халасле`};var g={en:`A classic dish from Hungary, featuring carp, yellow onion, tomato, red bell pepper. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Угорщина. Основні складники: короп, жовта цибуля, помідор, червоний солодкий перець. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var m=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 30 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 30 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:30,i:[[`carp`,950,`g`],[`water`,1400,`ml`],[`yellow-onion`,260,`g`],[`tomato`,220,`g`],[`red-bell-pepper`,160,`g`],[`sweet-paprika`,28,`g`]]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:3,i:[[`hot-paprika`,5,`g`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Add the listed ingredients to the pot. Keep at a gentle simmer for about 10 minutes, until tender and cooked through.`,ua:`Додайте зазначені складники до каструлі. Варіть за слабкого кипіння приблизно 10 хвилин до м’якості та готовності.`,t:[`simmering`],m:10,i:[[`fish-stock`,150,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`parsley`,12,`g`]]}];var d={slug:i,id:n,country:`HU`,region:s,servings:4,minutes:45,title:l,text:g,steps:m};export{a as country,d as default,n as id,r as minutes,s as region,o as servings,i as slug,m as steps,g as text,l as title};